import itertools

def langford(n):
    # backtracking with pruning
    seq = [0] * (2*n)
    # numbers to place: 1..n
    # We'll try placing numbers from largest to smallest for efficiency
    def backtrack(pos):
        if pos == 2*n:
            return True
        if seq[pos] != 0:
            return backtrack(pos+1)
        # try numbers from n down to 1
        for v in range(n, 0, -1):
            # check if v already placed
            # we can track used numbers
            pass
    # Better: use recursion with list of available numbers
    # Use algorithm: place each number v at positions i and i+v+1
    # We'll use recursion over numbers
    used = [False] * (n+1)
    def solve(v):
        if v == 0:
            return True
        # try to place v at all possible positions i such that i+v+1 < 2n and both empty
        for i in range(2*n - v - 1):
            if seq[i] == 0 and seq[i+v+1] == 0:
                seq[i] = seq[i+v+1] = v
                if solve(v-1):
                    return True
                seq[i] = seq[i+v+1] = 0
        return False
    if solve(n):
        return seq
    return None

